    case 'setItemFavorite':
      await dao.setItemFavorite(
        decodeInt(args['id']),
        isFavorite: args['isFavorite'] as bool,
      );
      return null;

    case 'setItemOverrideName':
      await dao.setItemOverrideName(
        decodeInt(args['id']),
        args['name'] as String?,
      );
      return null;

    case 'updateCollection':
      await dao.updateCollection(
        decodeInt(args['id']),
        name: args['name'] as String?,
        heroImagePath: args['heroImagePath'] as String?,
        description: args['description'] as String?,
        isHidden: args['isHidden'] as bool?,
        clearHeroImage: args.containsKey('clearHeroImage')
            ? args['clearHeroImage'] as bool
            : false,
        clearDescription: args.containsKey('clearDescription')
            ? args['clearDescription'] as bool
            : false,
      );
      return null;

