        startedAt: decodeDateTimeOrNull(args['startedAt']),
        completedAt: decodeDateTimeOrNull(args['completedAt']),
        lastActivityAt: decodeDateTimeOrNull(args['lastActivityAt']),
        clearStartedAt: args.containsKey('clearStartedAt')
