      await dao.updateItemAuthorComment(
        decodeInt(args['id']),
        args['comment'] as String?,
      );
      return null;

    case 'updateItemCollectionId':
      final bool value = await dao.updateItemCollectionId(
        decodeInt(args['id']),
        decodeIntOrNull(args['collectionId']),
      );
      return value;

    case 'updateItemFieldsBatch':
      await dao.updateItemFieldsBatch(
        asList(args['updates'])
            .map(
              (Object? e) => (
                decodeInt(asObject(e)[r'$1']),
                decodeRow(asObject(e)[r'$2']),
              ),
            )
            .toList(),
      );
      return null;

    case 'updateItemProgress':
      await dao.updateItemProgress(
        decodeInt(args['id']),
        currentSeason: decodeIntOrNull(args['currentSeason']),
        currentEpisode: decodeIntOrNull(args['currentEpisode']),
      );
      return null;

    case 'updateItemRewatchCount':
      await dao.updateItemRewatchCount(
