      );
      return null;

    case 'updateItemStatus':
      await dao.updateItemStatus(
        decodeInt(args['id']),
        decodeEnum<ItemStatus>(args['status'], ItemStatus.values),
        mediaType: decodeEnum<MediaType>(args['mediaType'], MediaType.values),
      );
      return null;

